'use strict';
const Shipping={
 canGenerate(){return Business.can('load:read')&&Business.can('document:generate')&&Business.can('inventory:export');},
 filters(route){const q=new URLSearchParams(location.search);return `<form id="shipping-filter" class="shipping-filters">${[['合同号','contract_no'],['客户名称','customer'],['出库单号','outbound_no'],['车牌号','vehicle_no']].map(([label,key])=>`<label><span>${label}</span><input name="${key}" value="${esc(q.get(key)||'')}" maxlength="160"></label>`).join('')}${route==='/export-shipments'?'<label>出库开始日期<input type="date" name="start" value="'+esc(q.get('start')||'')+'"></label><label>出库结束日期<input type="date" name="end" value="'+esc(q.get('end')||'')+'"></label>':''}<div class="business-toolbar"><button class="button primary">查询</button><a class="button secondary" href="${route}">重置</a></div></form>`;},
 bindFilters(route){$('shipping-filter').onsubmit=e=>{e.preventDefault();const q=new URLSearchParams(location.search);q.delete('page');for(const [k,v] of new FormData(e.target)){if(v.trim())q.set(k,v.trim());else q.delete(k);}Router.go(route+'?'+q);};},
 paging(data,route){return `<div class="business-toolbar shipping-pagination"><button id="shipping-prev" ${data.page===1?'disabled':''}>上一页</button><span>${data.page} / ${Math.max(1,Math.ceil(data.total/data.page_size))} · ${data.total} <span>条</span></span><button id="shipping-next" ${data.page*data.page_size>=data.total?'disabled':''}>下一页</button></div>`;},
 bindPaging(data,route){for(const [id,delta] of [['shipping-prev',-1],['shipping-next',1]])$(id).onclick=()=>{const q=new URLSearchParams(location.search);q.set('page',data.page+delta);Router.go(route+'?'+q);};},
 async list(){const r=await API.request('/shipping?'+new URLSearchParams(location.search));Router.page('出口发运记录',this.filters('/export-shipments')+`<div class="business-table"><table><thead><tr><th>装箱单号 / 正式出库单号</th><th>客户 / 合同</th><th>备货批次</th><th>车牌号</th><th>离场 / 出库日期</th><th>捆数 / 净重（吨）</th><th>Packing List</th><th>操作</th></tr></thead><tbody>${r.items.map(d=>`<tr><td><a data-no-i18n href="/outbounds/loads/${d.id}">${esc(d.packing_list_no||d.outbound_no)}</a><br><small>${d.posted?'已正式出库':'物流已审核 / 待正式出库'}</small></td><td><span data-no-i18n>${esc(d.customer_name)}</span><br><span data-no-i18n>${esc(d.contract_no||'—')}</span></td><td data-no-i18n>${esc(d.lot_no||'—')}</td><td data-no-i18n>${esc(d.shipping_vehicle_no)}</td><td data-no-i18n>${esc(d.outbound_date||'')}</td><td>${d.bundle_count}<br>${Tonnes.format(d.total_net_weight)}</td><td>${d.revision?'<span>已生成</span> · r'+d.revision:'尚未生成'}</td><td><a class="button secondary" href="/export-shipments/${d.id}">${d.revision?'查看 Packing List':this.canGenerate()?'生成 Packing List':'查看详情'}</a>${d.revision&&Business.can('inventory:export')?`<button class="button secondary" data-shipping-download="${d.id}">下载 Excel</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8">当前范围无正式出库车辆</td></tr>'}</tbody></table></div>`+this.paging(r,'/export-shipments'));this.bindFilters('/export-shipments');this.bindPaging(r,'/export-shipments');this.bindDownloads();},
 async download(id){try{const r=await API.request('/shipping/'+id+'/packing-list.xlsx',{binary:true}),url=URL.createObjectURL(r.blob),a=document.createElement('a');a.href=url;a.download=r.filename||r.fileName||'PackingList_'+id+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){notify(e.message);}},
 bindDownloads(){document.querySelectorAll('[data-shipping-download]').forEach(b=>b.onclick=()=>this.download(b.dataset.shippingDownload));},
 metric(label,value){return '<article><span>'+label+'</span><strong>'+Tonnes.format(value)+'</strong><span>吨</span></article>';},
 async detail(id){const d=await API.request('/shipping/'+id),fields=d.transport.fields,editable=Business.can('load:write'),labels={vehicle_no:'车牌号',trailer_one:'挂车一',trailer_two:'挂车二',driver_name:'司机姓名',passport_no:'护照号',container_no:'集装箱号',forwarder:'运输商',eb_license:'出口许可证号',destination:'目的地',buyer_information:'客户联系信息'};
 this.data=d;Router.page('装箱单 · '+d.outbound_no,`<p class="dialog-notice">${d.posted!==false?'已正式出库':'物流已审核 / 待正式出库'} · 物流经理审批后可生成Packing List，生产部经理审批后正式出库并扣减库存。</p><div class="shipping-kpis">${[['总捆包数',d.bundle_count],['总毛重（吨）',Tonnes.format(d.total_gross_weight)],['总净重（吨）',Tonnes.format(d.total_net_weight)],['单证版本',d.document?'r'+d.document.revision:'尚未生成']].map(([label,v])=>'<article><span>'+label+'</span><strong data-no-i18n>'+v+'</strong></article>').join('')}</div><p><span>客户</span>：<span data-no-i18n>${esc(d.customer_name)}</span> · <span>合同号</span>：<span data-no-i18n>${esc(d.contracts.join(' / ')||'—')}</span> · <span>装车日期</span>：<span data-no-i18n>${esc(d.document_date||d.outbound_date||'—')}</span></p><p><span>销售计划</span>：${d.plans.map(p=>`<a data-no-i18n href="/preparation/plans/${p.id}/shipping">${esc(p.code)}</a>`).join(' / ')} · <span>备货批次</span>：<span data-no-i18n>${esc(d.lots.join(' / '))}</span></p>
 ${d.document_stale?'<p class="dialog-notice">装车、客户或运输资料已变更，请重新生成Packing List。旧修订保留。</p>':''}${d.missing_weights.length?'<p class="error">原始重量缺失，暂不能生成Packing List：'+esc(d.missing_weights.join(' / '))+'</p>':''}
 <div class="business-toolbar"><a class="button secondary" href="/outbounds/loads/${id}">查看原装车单</a>${d.document&&!d.document_stale&&Business.can('inventory:export')?`<button class="button secondary" data-shipping-download="${id}">下载 Excel</button>`:''}</div>
 ${this.canGenerate()?'<form id="shipping-generate" class="shipping-generate"><label>生成说明<input name="reason" minlength="5" maxlength="1000" required value="'+(d.document?'':'根据物流审核装车明细生成')+'"></label><button class="button primary" '+(d.missing_weights.length?'disabled':'')+'>'+(d.document?'重新生成 Packing List':'生成 Packing List')+'</button><p id="shipping-generate-error" class="error" role="alert"></p></form>':''}
 <section id="packing-list-preview" class="packing-list-preview" aria-label="Packing List预览">${d.document_stale?'<p>重新生成后显示最新预览。</p>':d.document?'<p>正在载入预览…</p>':'<p>生成后可在此预览Packing List。</p>'}</section>
 <details class="shipping-history"><summary>单证生成与修改记录</summary>${(d.transport_changes||[]).map(c=>`<p><span>运输资料修改</span> · <span data-no-i18n>${esc(c.occurred_at)} · ${esc(c.actor_name||'')} · ${esc(c.reason||'')}</span></p>`).join('')}${d.revisions.map(r=>`<p><strong>r${r.revision}</strong> · <span data-no-i18n>${esc(r.generated_at)}</span> · <span data-no-i18n>${esc(r.reason)}</span></p>`).join('')||'<p>尚无生成记录</p>'}</details>`);
 if($('shipping-generate'))$('shipping-generate').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/shipping/'+id+'/packing-list',{method:'POST',body:{expected_revision:d.document?.revision||0,transport_version:d.transport.version,source_signature:d.source_signature,reason:e.target.elements.reason.value}});await this.detail(id);}catch(err){$('shipping-generate-error').textContent=err.message;e.submitter.disabled=false;}};
 this.bindDownloads();if(d.document&&!d.document_stale){try{const preview=await API.request('/shipping/'+id+'/packing-list/preview');this.drawPreview(preview.layout);}catch(e){$('packing-list-preview').textContent=e.message;}}
 },
 drawPreview(layout){const host=$('packing-list-preview');host.replaceChildren();const page=document.createElement('div');page.className='packing-sheet';const table=document.createElement('table');table.className='packing-sheet-table';table.setAttribute('data-no-i18n','');const widths=layout.columns.map(w=>Math.round(w*7+5)),heights=layout.rows.map(r=>r.height*4/3),colgroup=document.createElement('colgroup');for(const w of widths){const c=document.createElement('col');c.style.width=w+'px';colgroup.append(c);}table.append(colgroup);
 const coord=a=>{const m=a.match(/([A-Z]+)(\d+)/);return {row:Number(m[2])-1,col:[...m[1]].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1};},merges=new Map(),skip=new Set();for(const m of layout.merges){const [a,b]=m.split(':').map(coord);merges.set(a.row+':'+a.col,{rowSpan:b.row-a.row+1,colSpan:b.col-a.col+1});for(let r=a.row;r<=b.row;r++)for(let c=a.col;c<=b.col;c++)if(r!==a.row||c!==a.col)skip.add(r+':'+c);}
 const body=document.createElement('tbody');for(let r=0;r<layout.rows.length;r++){const tr=document.createElement('tr');tr.style.height=heights[r]+'px';for(let c=0;c<7;c++){if(skip.has(r+':'+c))continue;const x=layout.rows[r].cells[c],td=document.createElement('td');td.textContent=x.text;Object.assign(td,merges.get(r+':'+c)||{});td.style.fontFamily=x.font.name;td.style.fontSize=x.font.size+'pt';td.style.fontWeight=x.font.bold?'700':'400';td.style.fontStyle=x.font.italic?'italic':'normal';td.style.color=x.font.color||'#000';td.style.background=x.fill||'#fff';td.style.textAlign=x.alignment?.horizontal||(/^[-\d,]+(?:\.\d+)?$/.test(String(x.text))?'right':'left');td.style.verticalAlign=({center:'middle',distributed:'middle'})[x.alignment?.vertical]||x.alignment?.vertical||'bottom';td.style.whiteSpace=x.alignment?.wrapText?'pre-wrap':'pre';if(x.alignment?.shrinkToFit){const measure=document.createElement('canvas').getContext('2d');measure.font=(x.font.bold?'bold ':'')+(x.font.size*4/3)+'px "'+x.font.name+'"';const span=merges.get(r+':'+c)?.colSpan||1,available=widths.slice(c,c+span).reduce((a,b)=>a+b,0)-8,factor=Math.min(1,available/Math.max(1,measure.measureText(String(x.text)).width));td.style.fontSize=(x.font.size*factor).toFixed(2)+'pt';}if(x.alignment?.wrapText)td.style.overflowWrap='anywhere';for(const [side,b] of Object.entries(x.border)){if(b.style)td.style['border'+side[0].toUpperCase()+side.slice(1)]=(b.style==='double'?'3px double':b.style==='medium'||b.style==='thick'?'2px solid':'1px '+(b.style==='dotted'?'dotted':'solid'))+' '+(b.color||'#000');}tr.append(td);}body.append(tr);}table.append(body);page.append(table);page.style.width=widths.reduce((a,b)=>a+b,0)+'px';
 const position=(n,sizes)=>sizes.slice(0,Math.floor(n)).reduce((a,b)=>a+b,0)+(sizes[Math.floor(n)]||0)*(n%1);for(const image of layout.images){const img=document.createElement('img');img.alt='';img.src='data:image/'+image.extension+';base64,'+image.base64;img.style.position='absolute';img.style.left=position(image.tl.col,widths)+'px';img.style.top=position(image.tl.row,heights)+'px';if(image.br){img.style.width=(position(image.br.col,widths)-position(image.tl.col,widths))+'px';img.style.height=(position(image.br.row,heights)-position(image.tl.row,heights))+'px';}page.append(img);}host.append(page);},
 async plan(id){const p=await API.request('/shipping/plans/'+id);Router.page('销售计划发运进度 · '+p.plan_code,`<p data-no-i18n>${esc(p.customer_name)} · ${esc(p.contract_no||'—')}</p><div class="shipping-kpis">${'<article><span>计划发运数量（吨）</span><strong>'+PlanDisplay.format(p.planned_net_weight)+'</strong></article>'+this.metric('已备货数量',p.prepared_net_weight)+this.metric('已正式出库数量',p.shipped_net_weight)+this.metric('剩余待发数量',p.remaining_net_weight)}</div>${p.unknown_bundles?'<p>'+p.unknown_bundles+' <span>捆未完成检斤</span> · <span>已知备货净重</span> '+Tonnes.format(p.prepared_known_net_weight)+' <span>吨</span></p>':''}<h3>关联备货批次</h3><div class="business-table"><table><thead><tr><th>批次编号</th><th>状态</th></tr></thead><tbody>${p.allocations.map(a=>`<tr><td><a data-no-i18n href="/preparation/${a.id}">${esc(a.lot_no||a.code)}</a></td><td>${esc(V261.states[a.workflow_state]||a.workflow_state||'—')}</td></tr>`).join('')}</tbody></table></div><h3>正式出库车辆</h3><p><a class="button secondary" href="/export-shipments?plan_id=${id}">查看全部关联发运记录</a></p><div class="business-table"><table><thead><tr><th>出库单号</th><th>车牌号</th><th>捆数</th><th>净重（吨）</th></tr></thead><tbody>${p.shipments.items.map(l=>`<tr><td><a data-no-i18n href="/export-shipments/${l.id}">${esc(l.packing_list_no||l.outbound_no)}</a></td><td data-no-i18n>${esc(l.shipping_vehicle_no)}</td><td>${l.plan_bundles}</td><td>${Tonnes.format(l.plan_net_weight)}</td></tr>`).join('')||'<tr><td colspan="4">暂无正式出库车辆</td></tr>'}</tbody></table></div>`);},
 async planColumns(){if(!Business.can('plan:read'))return;const heading=[...document.querySelectorAll('#page-content > h3')].find(e=>/销售计划|Sales Plan/i.test(e.textContent)),table=heading?.nextElementSibling?.querySelector('table');if(!table)return;const data=await API.request('/shipping/plans'),map=new Map(data.items.map(p=>[p.plan_code,p]));table.id='plan-shipping-progress';const ths=table.querySelectorAll('thead th');ths[2].textContent='计划数量（吨）';for(const label of ['已备货数量（吨）','已正式出库数量（吨）','剩余待发数量（吨）']){const th=document.createElement('th');th.textContent=label;ths[3].before(th);}for(const row of table.querySelectorAll('tbody tr')){const p=map.get(row.cells[0].textContent.trim());if(!p)continue;const state=row.cells[3];for(const value of [p.prepared_net_weight,p.shipped_net_weight,p.remaining_net_weight]){const td=document.createElement('td');td.textContent=Tonnes.format(value);state.before(td);}const link=document.createElement('a');link.href='/preparation/plans/'+p.plan_id+'/shipping';link.textContent='发运进度';row.cells[row.cells.length-1].append(' ',link);if(p.unknown_bundles){const note=document.createElement('small');note.textContent=p.unknown_bundles+' 捆未完成检斤';row.cells[3].append(document.createElement('br'),note);}}I18n.apply();}
};
const v30Loads=Flow.loads.bind(Flow);Flow.loads=async function(){await v30Loads();const r=await API.request('/shipping/loads?'+new URLSearchParams(location.search)),filter=document.createElement('section');filter.innerHTML=Shipping.filters('/outbounds');$('page-content').prepend(filter);const table=document.querySelector('#page-content .business-table');table.innerHTML=`<table><thead><tr><th>装箱单号 / 装车单号</th><th>客户 / 合同</th><th>批次编号</th><th>车牌号</th><th>状态</th><th>操作</th></tr></thead><tbody>${r.items.map(l=>`<tr><td data-no-i18n>${esc(l.packing_list_no||l.outbound_no)}</td><td data-no-i18n>${esc(l.customer_name)}<br>${esc(l.contract_no||'—')}</td><td data-no-i18n>${esc(l.lot_no||'—')}</td><td data-no-i18n>${esc(l.shipping_vehicle_no)}</td><td>${UI.status(l.workflow_state||l.status,'loading',(l.workflow_state==='DEPARTED_PENDING'?(l.logistics_review_by?'待生产部经理审批出库':'待物流经理审核离场'):V26.states[l.workflow_state]||Flow.names[l.status]))}</td><td><a href="/outbounds/loads/${l.id}">详情 / 审批</a>${(l.packing_eligible??l.posted)?` <a class="button secondary" href="/export-shipments/${l.id}">${l.revision?'查看 Packing List':Shipping.canGenerate()?'生成 Packing List':'查看详情'}</a>`:''}</td></tr>`).join('')||'<tr><td colspan="6">无匹配装车记录</td></tr>'}</tbody></table>`;table.insertAdjacentHTML('afterend',Shipping.paging(r,'/outbounds'));Shipping.bindFilters('/outbounds');Shipping.bindPaging(r,'/outbounds');};
Flow.outbounds=Flow.loads;
const v30Load=Flow.load.bind(Flow);Flow.load=async function(id){await v30Load(id);const d=await API.request('/loads/'+id);if(await API.request('/shipping/'+id+'/eligibility').then(e=>e.packing_eligible??e.posted)){const bar=document.createElement('div');bar.className='business-toolbar';bar.innerHTML='<a class="button primary" id="generate-packing-list" href="/export-shipments/'+id+'">'+(Shipping.canGenerate()?'生成 Packing List':'查看 Packing List')+'</a>';$('page-content').prepend(bar);}};
const v30Allocations=Business.allocations.bind(Business);Business.allocations=async function(...args){await v30Allocations(...args);await Shipping.planColumns();};
Router.names['export-shipments']='出口发运记录';const v30Permission=Router.permission.bind(Router);Router.permission=path=>/^\/preparation\/plans\/[0-9a-f-]{36}\/shipping$/.test(path)?'plan:read':path.startsWith('/export-shipments')?'load:read':v30Permission(path);
const v30Init=Router.init.bind(Router);Router.init=async function(){this.add(/^\/export-shipments$/,()=>Shipping.list());this.add(/^\/export-shipments\/([0-9a-f-]{36})$/,id=>Shipping.detail(id));this.add(/^\/preparation\/plans\/([0-9a-f-]{36})\/shipping$/,id=>Shipping.plan(id));const r=await v30Init();for(const nav of document.querySelectorAll('.sidebar nav,.mobile-primary')){const out=nav.querySelector('[data-primary-route="outbounds"]'),shipping=nav.querySelector('[data-primary-route="export-shipments"]');if(out&&shipping)out.after(shipping);}I18n.apply();return r;};
